package main
import (
  "fmt"
  "sync"
  "counter" // path to the package
)

func main() {
  ac, _ := counter.NewAtomicCounter()
  var wg sync.WaitGroup
  increments := 1000
  for i := 0; i < 3; i++ {
    wg.Add(1)
    go func() {
      for j := 0; j < increments; j++ { ac.Inc() }
      wg.Done()
    }()
  }
  wg.Wait()
  fmt.Println("final:", ac.Get())
  ac.Close()
}
